const fs = require('fs');
const fsp = require('fs/promises');
const path = require('path');
const crypto = require('crypto');

// <2 hex>/<uuid> -- generated by the server only, never derived from user input.
const KEY_RE = /^[0-9a-f]{2}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/**
 * Local-disk blob store. The interface (newKey/put/copy/stat/stream/remove)
 * is deliberately small so it can be replaced by an S3/GCS implementation.
 */
class LocalStorage {
  constructor(baseDir) {
    this.base = path.resolve(baseDir);
    this.tmpDir = path.join(this.base, '.tmp'); // same filesystem => atomic rename
  }

  async init() {
    await fsp.mkdir(this.tmpDir, { recursive: true });
    await this.sweepTmp();
    if (!this._timer) {
      this._timer = setInterval(() => this.sweepTmp().catch(() => {}), 60 * 60 * 1000);
      this._timer.unref();
    }
  }

  /** Remove temp files left behind by aborted uploads or crashes (older than 1h). */
  async sweepTmp(maxAgeMs = 60 * 60 * 1000) {
    const now = Date.now();
    for (const f of await fsp.readdir(this.tmpDir)) {
      const p = path.join(this.tmpDir, f);
      try {
        const st = await fsp.stat(p);
        if (now - st.mtimeMs > maxAgeMs) await fsp.unlink(p);
      } catch (_) { /* raced with another cleanup */ }
    }
  }

  newKey() {
    const id = crypto.randomUUID();
    return `${id.slice(0, 2)}/${id}`;
  }

  pathFor(key) {
    if (!KEY_RE.test(key)) throw new Error('Invalid storage key');
    const full = path.join(this.base, key);
    if (!full.startsWith(this.base + path.sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(tmpPath, key) {
    const dest = this.pathFor(key);
    await fsp.mkdir(path.dirname(dest), { recursive: true });
    await fsp.rename(tmpPath, dest);
  }

  async copy(srcKey, destKey) {
    const dest = this.pathFor(destKey);
    await fsp.mkdir(path.dirname(dest), { recursive: true });
    await fsp.copyFile(this.pathFor(srcKey), dest, fs.constants.COPYFILE_EXCL);
  }

  async stat(key) {
    return fsp.stat(this.pathFor(key));
  }

  stream(key) {
    return fs.createReadStream(this.pathFor(key));
  }

  async remove(key) {
    try {
      await fsp.unlink(this.pathFor(key));
    } catch (e) {
      if (e.code !== 'ENOENT') throw e;
    }
  }

  /** Delete a temp upload file; missing is fine (it may already have been moved). */
  async discard(tmpPath) {
    if (!tmpPath) return;
    try { await fsp.unlink(tmpPath); } catch (e) { if (e.code !== 'ENOENT') throw e; }
  }

  hashFile(p) {
    return new Promise((resolve, reject) => {
      const h = crypto.createHash('sha256');
      fs.createReadStream(p).on('error', reject).on('data', (d) => h.update(d)).on('end', () => resolve(h.digest('hex')));
    });
  }
}

module.exports = LocalStorage;
